   886    *((char *) mempcpy (elf->state.ar.raw_name, ar_hdr->ar_name, 16)) = '\0';
   887
   888    elf_ar_hdr = &elf->state.ar.elf_ar_hdr;
   889
   890    /* Now convert the `struct ar_hdr' into `Elf_Arhdr'.
   891       Determine whether this is a special entry.  */
