   894        if (ar_hdr->ar_name[1] == ' '
   895            && memcmp (ar_hdr->ar_name, "/               ", 16) == 0)
   896          /* This is the index.  */
   897          elf_ar_hdr->ar_name = memcpy (elf->state.ar.ar_name, "/", 2);
